  "bd.intro": "Plocha roviny = půdorysná plocha ÷ cos(sklon) − okna, komíny, otvory a vikýře. Délka linie = √(Δx² + Δy² + Δz²). Najetím myší na plochu nebo linii se zvýrazní v půdorysu; čísla ploch jsou vidět i tam.",
