  "res.ridgeHeight": "Výška hrebeňa {v} m",
  "res.warn.title": "Strechu skontrolujte",
  "res.joinedTo": "napojené: {names}",
  "res.warn.covered": "Táto budova nemá žiadnu viditeľnú strešnú plochu: leží vnútri inej budovy alebo pod ňou. Posuňte alebo zmažte jednu z nich.",
  "res.warn.outside_outline": "Časť strechy leží mimo obrys odkvapu (až {v} m). Skontrolujte sklony a presahy.",
  "res.warn.overlapping_faces": "Niektoré plochy strechy sa pretínajú alebo prekrývajú ({v} m²). Výmery nemusia zodpovedať skutočnosti.",
  "res.warn.area_mismatch": "Vykázaná plocha sa od plôch strechy líši o {v} %. Výmeru overte.",
  "res.warn.merged_walls": "Steny {a} a {b} ležia v jednej priamke s rovnakou výškou odkvapu aj presahom, a preto sa počítajú ako jedna stena so sklonom steny {a}. Sklon a zlomy steny {b} sa nepoužijú. Ak majú platiť, zmeňte pri jednej z nich výšku odkvapu alebo presah.",
  "res.warn.plane_over_wall": "Rovina steny {a} má rovnaký smer aj sklon ako rovina steny {b} a leží o {v} m vyššie, takže pokračuje cez odkvap steny {b} ako jedna plocha a táto časť nemá vlastný hrebeň. Ak ho má mať, zadajte jej bočné steny ako odkvap a čelnú stenu ako štít alebo valbu.",
  "res.warn.merged_planes": "Roviny stien {a} a {b} ležia takmer v jednej rovine (rozdiel {v} cm), preto sú vypočítané ako jedna plocha bez schodu.",
  "res.warn.wing_joined": "Krídlo so stenami {walls} má odkvap tak nízko, že jeho strecha nedosiahne na strechu domu. Je preto vypočítané ako prístavok k stene domu: jeho strecha končí pri stene oplechovaním.",
  "res.warn.cut_exceeds_face": "Z niektorej plochy strechy sa odpočítava viac, než koľko plocha má ({v} m² pod nulou), takže plocha strechy vychádza menšia. Zvyčajne ide o strešné okno väčšie než jeho plocha (cm namiesto m, zamenená šírka a výška). Skontrolujte okná.",
  "res.warn.dormer_off_roof": "Vikier {n} neleží na žiadnej strešnej ploche, a preto sa do výsledku nepočíta (plocha, čiary ani materiál). Presuňte ho na strechu alebo ho zmažte.",
  "res.warn.window_off_roof": "Strešné okno {n} neleží na žiadnej strešnej ploche, a preto sa od plochy nič neodpočíta a do výsledku sa nepočíta. Presuňte ho na strechu alebo ho zmažte.",
  "res.warn.chimney_off_roof": "Komín {n} neleží na žiadnej strešnej ploche, a preto zo strechy nič nevyreže a do výsledku sa nepočíta. Presuňte ho na strechu alebo ho zmažte.",
  "res.warn.opening_off_roof": "Otvor {n} neleží na žiadnej strešnej ploche, a preto zo strechy nič nevyreže a do výsledku sa nepočíta. Presuňte ho na strechu alebo ho zmažte.",
  "res.warn.not_calculated_by_core": "Táto strecha bola vypočítaná náhradným výpočtom, nie štandardným. Výsledok sa môže od štandardného výpočtu líšiť; strechu skontrolujte.",
  "res.warn.doubled_line": "Niektoré čiary strechy ležia na sebe ({v} m sa počíta dvakrát), zvyčajne tam, kde sa dotýkajú strechy dvoch budov. Skontrolujte dĺžky čiar pri spoji budov, najmä nárožia a štítové hrany.",
  "res.warn.far_from_origin": "Budova leží {v} km od počiatku výkresu. Tak ďaleko výpočet stráca presnosť a plocha strechy môže vyjsť nesprávne. Posuňte pôdorys bližšie k počiatku (do 2,5 km).",
  "res.warn.no_roof_area": "Strecha tejto budovy vychádza s nulovou plochou. Skontrolujte, či ju celú nezaberá komín alebo otvor (cm namiesto m), a výšky odkvapov.",
  "res.warn.objects_overlap": "Niektoré prvky na streche ležia cez seba (okná, komíny, otvory alebo vikiere; počet dvojíc: {n}). Každý sa napriek tomu odpočíta a počíta celý. Skontrolujte, či niektorý nie je zadaný dvakrát.",
  "res.warn.dormer_above_roof": "Vikier siaha {v} m nad najvyšší bod strechy, na ktorej stojí, takže jeho strecha strešnú plochu pred hrebeňom nedosiahne a plocha aj dĺžky čiar vychádzajú príliš veľké. Skontrolujte sklon a výšku odkvapu vikiera.",
  "res.warn.inside_another": "Táto budova leží celá vnútri stien inej budovy a jej strecha mimo rovín strechy okolo sa napriek tomu počíta do plochy aj dĺžok čiar. Skontrolujte, či nejde o kópiu alebo budovu nakreslenú dvakrát. Ak budova vyznačuje časť strešnej plochy (napríklad iný materiál), ponechajte ju a dajte jej sklon a výšku odkvapu strechy okolo.",
  "res.warn.hidden_under_neighbour": "{v} m² strechy tejto budovy leží vnútri stien susednej budovy pod jej strechou: je skrytá na jej povale, a napriek tomu sa počíta do plochy. Zvyčajne ide o presah steny, ktorá stojí pri stene susednej budovy. Ak ho nastavíte na 0, skrytá časť zmizne.",
  "res.warn.uncovered_plan": "{v} m² pôdorysu tejto budovy (so stenami a presahmi) nemá nad sebou žiadnu strešnú plochu, takže plocha strechy vychádza menšia. Pri spojení striech sa časť plôch stratila. Skontrolujte strechu pri spoji budov.",
  "opening.tooLarge.title": "Okno nezmenené",
  "opening.tooLarge": "Okno {n} ({a} m²) je väčšie než zvyšok strešnej plochy, na ktorej leží ({f} m²). Skontrolujte šírku a výšku (v metroch, v rovine strechy).",
