  "bd.title": "Postup výpočtu",
  "bd.intro": "Plocha roviny = pôdorysná plocha ÷ cos(sklon) − okná, komíny, otvory a vikiere. Dĺžka línie = √(Δx² + Δy² + Δz²). Po prejdení myšou na plochu alebo líniu sa zvýrazní v pôdoryse; čísla plôch sú viditeľné aj tam.",
  "bd.open": "Podrobný výpočet",
  "bdd.faceTitle": "Plocha {n}: podrobný výpočet",
