  "bdd.corners": "Rohy plochy (m)",
  "bdd.height": "výška z",
  "bdd.plan": "Pôdorysná plocha S (Gaussov vzorec)",
  "bdd.planHint": "Pre každú dvojicu susedných rohov (po obvode, za posledným rohom nasleduje prvý) sa vypočíta xᵢ · yᵢ₊₁ − xᵢ₊₁ · yᵢ; polovica absolútnej hodnoty súčtu je plocha priemetu do pôdorysu. Rohov: {n}.",
  "bdd.pitch": "Sklon α a prepočet na plochu v sklone",
  "bdd.sloped": "Plocha v sklone A",
  "bdd.check3d": "Kontrola: plocha vypočítaná priamo z priestorových súradníc rohov (Newellova metóda) je {v} m².",
  "bdd.engine": "Jadro výpočtu udáva hrubú plochu {v} m² (o {diff} m² inak ako vzorec); ďalej sa počíta s ňou. Jadro počíta s jednoduchou presnosťou a pri spojených strechách aj s ich prienikom, preto sa môže od vzorca líšiť.",
  "bdd.deduct": "Odpočty (okná, komíny, otvory, vikiere, prieniky striech)",
  "bdd.deductHint": "Odpočty na celej streche tejto budovy: {list}, spolu {total} m².",
  "bdd.noDeduct": "Z tejto plochy sa nič neodpočítava.",
  "bdd.result": "Výsledok (zaokrúhlené na stotiny):",
  "bdd.ends": "Koncové body línie (m)",
  "bdd.diff": "Rozdiely súradníc a ich druhé mocniny",
  "bdd.length": "Dĺžka línie",
  "bdd.typed": "Dĺžka tejto línie bola zadaná ručne, nepočíta sa z bodov.",
  "bdd.rounding": "Každé číslo je presná hodnota výpočtu zaokrúhlená na uvedené miesta. Súradnice a sklony sú hodnoty jadra výpočtu v jednoduchej presnosti, preto sa napr. 183,62 ukáže ako 183,6199951172. Prepočet kroku zo zobrazených čísel sa líši najviac o jednotku na poslednom mieste (pri súčte navyše o pol jednotky za každý sčítanec); výsledok na stotiny sedí.",
  "bd.sumNote": "Sčítance sú ukázané s toľkými miestami, aby dávali súčet presne; ten sa potom zaokrúhli na stotiny (≐). Znak ≈ znamená, že sa súčet líši len o výpočtový šum.",
