  "conn.title": "Pripojiť AI k Tectore",
  "conn.lead": "Tectora má zabudovaný MCP server. Po pripojení môže AI z technického výkresu sama založiť strechu a upravovať ju; každú zmenu tu hneď uvidíte, zvýraznenú, s popisom a možnosťou ju vrátiť.",
