  "conn.ask.claude": "pri otázke na nástroj Tectory zvoľte „Always allow“, alebo v Customize › Connectors › Tectora nastavte nástroje na „Always allow“. Tectora hovorí, ktoré nástroje iba čítajú, takže môžete natrvalo povoliť čítanie a potvrdzovať len zmeny.",
