  "res.warn.opening_off_roof": "Opening {n} lies on no roof face, so it cuts nothing and is left out of the result. Move it onto the roof or delete it.",
  "res.warn.not_calculated_by_core": "This roof was calculated by the fallback calculation, not the standard one. The result may differ from the standard calculation; check the roof.",
  "res.warn.doubled_line": "Some roof lines lie on top of each other ({v} m is counted twice), usually where the roofs of two buildings touch. Check the line lengths at the join, especially hips and verges.",
  "res.warn.far_from_origin": "The building stands {v} km from the origin of the drawing. That far out the calculation loses precision and the roof area can come out wrong. Move the plan closer to the origin (within 2.5 km).",
  "res.warn.no_roof_area": "The roof of this building comes out with no area. Check whether a chimney or opening takes all of it (cm typed as m), and the eave heights.",
  "res.warn.objects_overlap": "Some objects on the roof lie on top of each other (windows, chimneys, openings or dormers; pairs: {n}). Each is still deducted and counted in full. Check whether one of them was entered twice.",
  "res.warn.dormer_above_roof": "A dormer rises {v} m above the highest point of the roof it sits on, so its roof does not reach the roof face before the ridge and the area and line lengths come out too large. Check the dormer's pitch and eave height.",
  "res.warn.inside_another": "This building lies entirely within the walls of another building, and its roof, outside the planes of the roof around it, still counts towards the area and line lengths. Check whether it is a copy or a building drawn twice. If the building marks part of a roof face (for example another material), keep it and give it the pitch and eave height of the roof around it.",
  "res.warn.hidden_under_neighbour": "{v} m² of this building's roof lies inside the walls of the neighbouring building, under its roof: it is hidden in that attic yet counts towards the area. Usually this is the overhang of a wall standing against the neighbouring building. Setting that overhang to 0 removes the hidden part.",
  "res.warn.uncovered_plan": "{v} m² of this building's plan (walls and overhangs) has no roof face over it, so the roof area comes out too small. Faces were lost where the roofs are joined. Check the roof at the join of the buildings.",
