  "bd.title": "How it was calculated",
  "bd.intro": "Face area = plan area ÷ cos(pitch) − windows, chimneys, openings and dormers. Line length = √(Δx² + Δy² + Δz²). Point at a face or line to highlight it in the plan; face numbers are shown there too.",
  "bd.open": "Detailed calculation",
  "bdd.faceTitle": "Face {n}: detailed calculation",
  "bdd.lineTitle": "{code} {label} {n}: detailed calculation",
  "bdd.corners": "Face corners (m)",
  "bdd.height": "height z",
  "bdd.plan": "Plan area S (shoelace formula)",
  "bdd.planHint": "For each pair of neighbouring corners (around the outline, the last corner followed by the first) take xᵢ · yᵢ₊₁ − xᵢ₊₁ · yᵢ; half the absolute value of the sum is the area projected on the plan. Corners: {n}.",
  "bdd.pitch": "Pitch α and conversion to the sloped area",
  "bdd.sloped": "Sloped area A",
  "bdd.check3d": "Check: the area calculated directly from the corners' 3D coordinates (Newell's method) is {v} m².",
  "bdd.engine": "The calculation core gives a gross area of {v} m² ({diff} m² from the formula); that value is used from here on. The core works in single precision and, where roofs are joined, also cuts them against each other, so it can differ from the formula.",
  "bdd.deduct": "Deductions (windows, chimneys, openings, dormers, joined roofs)",
  "bdd.deductHint": "Deductions on this building's whole roof: {list}, {total} m² in total.",
  "bdd.noDeduct": "Nothing is deducted from this face.",
  "bdd.result": "Result (rounded to hundredths):",
  "bdd.ends": "End points of the line (m)",
  "bdd.diff": "Coordinate differences and their squares",
  "bdd.length": "Line length",
  "bdd.typed": "This line's length was typed in by hand, not calculated from its points.",
  "bdd.rounding": "Every number is the exact value of the calculation rounded to the places shown. Coordinates and pitches are the calculation core's single-precision values, so 183.62 for example shows as 183.6199951172. Redoing a step from the numbers shown differs by at most one unit in the last place (for a sum, half a unit more per term); the result to hundredths matches.",
  "bd.sumNote": "Terms are shown with as many places as it takes for them to add up exactly; the sum is then rounded to hundredths (≐). ≈ means the sum differs only by floating-point noise.",
  "bd.otherCuts": "cut by another building's roof",
  "bd.lineOpen": "√(Δx² + Δy² + Δz²)",
  "bd.engineShort": "calculation core {v} m²",
  "bd.cladGable": "clad gable, wall {n}",
  "bdd.cladCore": "The calculation core counts {v} m²; the pieces add up to {s} m².",
  "bdd.cladCorners": "corners (m)",
  "bdd.piece": "Piece {n}",
  "bdd.cladHint": "A clad gable is vertical, so its area is taken in the plane of the wall: u is the horizontal distance along the wall from the first corner, z the height.",
  "bdd.cladTitle": "Clad gable, wall {n}: detailed calculation",
  "bdd.manualOut": "The pitch of {p}° is outside 0–90° or nearly vertical, so the face counts no area (0 m²).",
  "bdd.vertical": "The face is vertical (cos α ≈ 0), so its area cannot be taken from the plan; the area is the calculation core's.",
  "bdd.check3dRound": "Check: the area from the 3D corner coordinates (Newell's method) is {v} m²; the difference of {d} m² matches the rounding of the coordinates in the calculation core (single precision).",
  "bdd.check3dOff": "Check: the area from the 3D corner coordinates (Newell's method) is {v} m²; the corners lie up to {mm} mm off one plane.",
