  "conn.title": "Connect an AI to Tectora",
  "conn.lead": "Tectora has a built-in MCP server. Once connected, an AI can create and edit a roof from a technical drawing; you see every change here right away, highlighted, with a description and a way to revert it.",
  "conn.terminal": "Run in a terminal:",
  "conn.copy": "Copy",
  "conn.copied": "Copied",
  "conn.howTitle": "How it works",
  "conn.how1": "The AI reads the drawing and calls Tectora's tools (create roof, change pitch, …).",
  "conn.how2": "Every save shows up here instantly: changed walls glow orange and a banner says what the AI did.",
  "conn.how3": "You just review the change and accept it, or revert it with one click.",
  "conn.askTitle": "So the AI does not ask at every step",
  "conn.ask.claude": "when it asks about a Tectora tool, choose “Always allow”, or set the tools to “Always allow” under Customize › Connectors › Tectora. Tectora marks which tools only read, so you can allow reading for good and confirm only changes.",
  "conn.ask.antigravity": "under Settings › General › Global Permissions choose the Permission Preset “Turbo”; MCP tools then run without asking.",
  "conn.ask.other": "Other apps usually have a similar choice on the permission prompt. You still see every AI change here and can revert it.",
  "conn.follow": "Automatically open the job the AI is working on",
  "conn.apps": "AI apps on this computer",
  "conn.loading": "Looking for AI apps…",
