  "conn.restart.claude_desktop": "Done. Quit Claude Desktop completely (⌘Q on a Mac; on Windows right-click its icon by the clock › Quit) and open it again. Then tell it, for example: “Here is the drawing, create the roof in Tectora.”",
  "conn.restart.codex": "Done. Quit the ChatGPT app (⌘Q on a Mac) and open it again, or start a new Codex session in the terminal or your editor.",
  "conn.restart.antigravity": "Done. In Antigravity open Settings › Customizations and press Refresh under Installed MCP Servers, or open the app again.",
