  "bd.title": "Rechenweg",
  "bd.intro": "Flächeninhalt = Grundrissfläche ÷ cos(Neigung) − Fenster, Schornsteine, Öffnungen und Gauben. Linienlänge = √(Δx² + Δy² + Δz²). Zeigen Sie auf eine Fläche oder Linie, um sie im Grundriss hervorzuheben; dort stehen auch die Flächennummern.",
  "bd.open": "Ausführliche Berechnung",
  "bdd.faceTitle": "Fläche {n}: ausführliche Berechnung",
  "bdd.lineTitle": "{code} {label} {n}: ausführliche Berechnung",
  "bdd.corners": "Ecken der Fläche (m)",
  "bdd.height": "Höhe z",
  "bdd.plan": "Grundrissfläche S (Gaußsche Flächenformel)",
  "bdd.planHint": "Für jedes Paar benachbarter Ecken (entlang des Umrisses, auf die letzte Ecke folgt die erste) wird xᵢ · yᵢ₊₁ − xᵢ₊₁ · yᵢ gebildet; die Hälfte des Betrags der Summe ist die Fläche im Grundriss. Ecken: {n}.",
  "bdd.pitch": "Neigung α und Umrechnung auf die geneigte Fläche",
  "bdd.sloped": "Geneigte Fläche A",
  "bdd.check3d": "Kontrolle: Die direkt aus den räumlichen Koordinaten der Ecken berechnete Fläche (Newell-Verfahren) beträgt {v} m².",
  "bdd.engine": "Der Rechenkern liefert eine Bruttofläche von {v} m² ({diff} m² Abweichung von der Formel); mit diesem Wert wird weitergerechnet. Der Kern rechnet mit einfacher Genauigkeit und verschneidet verbundene Dächer miteinander, daher kann er von der Formel abweichen.",
  "bdd.deduct": "Abzüge (Fenster, Schornsteine, Öffnungen, Gauben, Verschneidungen)",
  "bdd.deductHint": "Abzüge auf dem ganzen Dach dieses Gebäudes: {list}, zusammen {total} m².",
  "bdd.noDeduct": "Von dieser Fläche wird nichts abgezogen.",
  "bdd.result": "Ergebnis (auf Hundertstel gerundet):",
  "bdd.ends": "Endpunkte der Linie (m)",
  "bdd.diff": "Koordinatendifferenzen und ihre Quadrate",
  "bdd.length": "Linienlänge",
  "bdd.typed": "Die Länge dieser Linie wurde von Hand eingegeben und nicht aus den Punkten berechnet.",
  "bdd.rounding": "Jede Zahl ist der exakte Wert der Berechnung, gerundet auf die angezeigten Stellen. Koordinaten und Neigungen sind Werte des Rechenkerns in einfacher Genauigkeit, daher erscheint z. B. 183,62 als 183,6199951172. Eine Nachrechnung aus den angezeigten Zahlen weicht um höchstens eine Einheit der letzten Stelle ab (bei einer Summe zusätzlich eine halbe Einheit je Summand); das Ergebnis auf Hundertstel stimmt.",
  "bd.sumNote": "Die Summanden stehen mit so vielen Stellen da, dass sie die Summe genau ergeben; diese wird dann auf Hundertstel gerundet (≐). ≈ bedeutet, dass die Summe nur um Rechenrauschen abweicht.",
  "bd.otherCuts": "Verschneidung mit dem Dach eines anderen Gebäudes",
  "bd.lineOpen": "√(Δx² + Δy² + Δz²)",
  "bd.engineShort": "Rechenkern {v} m²",
