  "conn.title": "KI mit Tectora verbinden",
  "conn.lead": "Tectora hat einen eingebauten MCP-Server. Nach dem Verbinden kann eine KI aus einer technischen Zeichnung ein Dach anlegen und bearbeiten; jede Änderung sehen Sie hier sofort, hervorgehoben, mit Beschreibung und der Möglichkeit, sie rückgängig zu machen.",
  "conn.terminal": "Im Terminal ausführen:",
  "conn.copy": "Kopieren",
  "conn.copied": "Kopiert",
  "conn.howTitle": "So funktioniert es",
  "conn.how1": "Die KI liest die Zeichnung und ruft Tectoras Werkzeuge auf (Dach anlegen, Neigung ändern, …).",
  "conn.how2": "Jede Speicherung erscheint sofort: geänderte Wände leuchten orange, oben steht, was die KI getan hat.",
  "conn.how3": "Sie prüfen die Änderung nur und übernehmen oder verwerfen sie mit einem Klick.",
  "conn.askTitle": "Damit die KI nicht bei jedem Schritt fragt",
  "conn.ask.claude": "wählen Sie bei der Frage zu einem Tectora-Werkzeug „Always allow“ oder stellen Sie die Werkzeuge unter Customize › Connectors › Tectora auf „Always allow“. Tectora kennzeichnet, welche Werkzeuge nur lesen, so können Sie das Lesen dauerhaft erlauben und nur Änderungen bestätigen.",
  "conn.ask.antigravity": "wählen Sie unter Settings › General › Global Permissions das Permission Preset „Turbo“; MCP-Werkzeuge laufen dann ohne Rückfrage.",
  "conn.ask.other": "Andere Apps haben meist eine ähnliche Wahl direkt bei der Berechtigungsfrage. Jede Änderung der KI sehen Sie hier trotzdem und können sie rückgängig machen.",
